<script lang="ts">
 import { onMount } from 'svelte';
 type App='chrome'|'files'|'settings'|'terminal'|'about';
 const apps=[{id:'chrome' as App,name:'Chrome',icon:'🌐',color:'#4285f4'},{id:'files' as App,name:'Arquivos',icon:'📁',color:'#fbbc04'},{id:'settings' as App,name:'Configurações',icon:'⚙️',color:'#5f6368'},{id:'terminal' as App,name:'Terminal',icon:'›_',color:'#202124'},{id:'about' as App,name:'Sobre',icon:'ℹ️',color:'#1a73e8'}];
 let locked=true,launcher=false,quick=false,notify=false,dark=false,wifi=true,bluetooth=true,search='',active:App|null=null,minimized:App[]=[]; let volume=72,brightness=80,time='',date='';
 $: filtered=apps.filter(a=>a.name.toLowerCase().includes(search.toLowerCase()));
 function openApp(id:App){active=id;minimized=minimized.filter(x=>x!==id);launcher=false;quick=false}
 function close(){active=null}
 function minimize(){if(active&&!minimized.includes(active))minimized=[...minimized,active];active=null}
 function lock(){locked=!locked;launcher=quick=notify=false}
 function toggleDark(){dark=!dark;localStorage.setItem('chromeos-dark',String(dark))}
 onMount(()=>{dark=localStorage.getItem('chromeos-dark')==='true';const tick=()=>{const d=new Date();time=d.toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});date=d.toLocaleDateString('pt-BR',{weekday:'short',day:'2-digit',month:'short'})};tick();const t=setInterval(tick,1000);return()=>clearInterval(t)})
</script>
<svelte:window on:keydown={(e)=>{if(e.key==='Escape'){launcher=quick=notify=false}if((e.ctrlKey||e.metaKey)&&e.key==='l'){e.preventDefault();lock()}if(e.key==='F6'){launcher=!launcher}}}/>
<div class="os" class:dark>
{#if locked}<section class="lock"><div class="lockclock">{time}</div><div class="lockbackdrop"></div><div class="profile"><div class="avatar">Y</div><h1>Convidado</h1><p>ChromeOS Web</p><button on:click={lock}>Entrar</button></div><small>⌁ Rede conectada　 🔋 100%</small></section>
{:else}<main class="desktop" on:click={()=>{launcher=quick=notify=false}}><div class="label"><span class="brandmark">●</span> ChromeOS Web</div>{#if active}<section class="window" on:click|stopPropagation><header><div class="controls"><button class="r" on:click={close}>×</button><button class="y" on:click={minimize}>−</button><button class="g">□</button></div><b>{apps.find(a=>a.id===active)?.icon} {apps.find(a=>a.id===active)?.name}</b></header>{#if active==='chrome'}<div class="chrome"><div class="tabs"><span class="tab active">Nova guia　×</span><span class="newtabbtn">＋</span></div><div class="toolbar"><button>←</button><button>→</button><button>↻</button><div>🔒　Pesquisar ou digitar um endereço</div><button>⋮</button></div><div class="newtab"><strong>G</strong><div class="searchbox">Pesquisar na Web　⌕</div><div class="shortcuts"><button on:click={()=>openApp('files')}>📁<small>Arquivos</small></button><button>＋<small>Adicionar atalho</small></button></div></div></div>{:else if active==='files'}<div class="files"><aside><h3>Arquivos</h3><span class="selected">⌂ Meus arquivos</span><span>☁ Google Drive</span><span>⬇ Downloads</span></aside><article><div class="filehead"><h2>Meus arquivos</h2><button>⋮</button></div><div class="grid"><div>📁<small>Downloads</small></div><div>📁<small>Documentos</small></div><div>📁<small>Imagens</small></div><div>📄<small>Bem-vindo.txt</small></div></div></article></div>{:else if active==='settings'}<div class="settings"><aside><h3>Configurações</h3><span class="selected">⚙ Geral</span><span>🌐 Rede</span><span>📶 Wi‑Fi</span><span>🎨 Personalização</span><span>🔒 Privacidade</span></aside><article><h2>Configurações</h2><label>Wi‑Fi <input type="checkbox" bind:checked={wifi}/></label><label>Bluetooth <input type="checkbox" bind:checked={bluetooth}/></label><label>Modo escuro <input type="checkbox" bind:checked={dark}/></label><label>Brilho <input type="range" bind:value={brightness}/></label><label>Volume <input type="range" bind:value={volume}/></label></article></div>{:else if active==='terminal'}<div class="terminal">ChromeOS Web Terminal<br/><br/><span>guest@chromeos:~$</span> echo "Olá, ChromeOS!"<br/>Olá, ChromeOS!<br/><span>guest@chromeos:~$</span> _</div>{:else}<div class="about"><div>◉</div><h1>ChromeOS Web</h1><p>Experiência independente inspirada no ChromeOS.</p><small>Web Edition · Svelte 5 · Vite</small></div>{/if}</section>{/if}</main>
{#if launcher}<section class="launcher" on:click|stopPropagation><div class="search">🔍 <input autofocus bind:value={search} placeholder="Pesquisar apps, arquivos e configurações"/></div><div class="apps">{#each filtered as a}<button on:click={()=>openApp(a.id)}><i style={`background:${a.color}`}>{a.icon}</i><small>{a.name}</small></button>{/each}</div><footer>⌕ Pesquisa <span>Convidado</span></footer></section>{/if}
{#if quick}<section class="quick" on:click|stopPropagation><header><div><b>Convidado</b><small>ChromeOS Web</small></div><button on:click={()=>openApp('settings')}>⚙</button></header><div class="tiles"><button class:on={wifi} on:click={()=>wifi=!wifi}>📶<small>Wi‑Fi<br/>{wifi?'Conectado':'Desativado'}</small></button><button class:on={bluetooth} on:click={()=>bluetooth=!bluetooth}>ᛒ<small>Bluetooth<br/>{bluetooth?'Ativado':'Desativado'}</small></button></div><label>☀ <input type="range" bind:value={brightness}/></label><label>🔊 <input type="range" bind:value={volume}/></label><div class="actions"><button on:click={toggleDark}>{dark?'☀':'☾'} Tema</button><button on:click={lock}>🔒 Bloquear</button><button on:click={()=>location.reload()}>⟳ Reiniciar</button></div></section>{/if}
{#if notify}<section class="notify" on:click|stopPropagation><b>Notificações</b><div>🎉<strong>Tudo em dia</strong><small>Não há novas notificações.</small></div></section>{/if}
<nav class="shelf" on:click|stopPropagation><button class="launcherbtn" on:click={()=>launcher=!launcher}>◉</button><div class="pins">{#each apps.slice(0,4) as a}<button class:running={active===a.id||minimized.includes(a.id)} on:click={()=>openApp(a.id)}><span style={`background:${a.color}`}>{a.icon}</span></button>{/each}</div><span class="spacer"></span><button on:click={()=>notify=!notify}>🔔</button><button class="status" on:click={()=>quick=!quick}>📶　🔋　<b>{time}</b></button></nav>{/if}
</div>
<style>
