 input{flex:1;border:0;outline:0;background:transparent;color:inherit;font-size:15px}.apps{display:grid;grid-template-columns:repeat(5,1fr);margin-top:12px}.apps button{border:0;background:transparent;color:inherit;padding:15px;border-radius:13px;display:flex;flex-direction:column;align-items:center;gap:8px;cursor:pointer}.apps button:hover{background:#0000000b}.apps i{width:46px;height:46px;border-radius:13px;display:grid;place-items:center;font-style:normal;font-size:25px;box-shadow:0 2px 5px #0002}.launcher footer{display:flex;justify-content:space-between;border-top:1px solid #ddd;margin-top:8px;padding:10px;font-size:12px}.quick{right:18px;bottom:88px;width:360px;padding:18px}.quick header{display:flex;justify-content:space-between;align-items:center}.quick header small{display:block;color:#777;margin-top:3px}.quick header button{border:0;background:transparent;font-size:20px}.tiles{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:15px 0}.tiles button{border:0;border-radius:13px;padding:12px;text-align:left;background:#e8eaed;cursor:pointer}.dark .tiles button{background:#3c4043;color:#fff}.tiles button.on{background:#d2e3fc;color:#174ea6}.tiles small{display:block;margin-top:5px}.quick label{display:flex;gap:8px;margin:15px 0}.quick label input{flex:1}.actions{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.actions button{border:0;border-radius:12px;padding:10px;font-size:11px;cursor:pointer}.notify{right:18px;bottom:88px;width:320px;padding:18px}.notify div{margin-top:15px;padding:25px;background:#fff8;border-radius:14px;text-align:center}.notify strong,.notify small{display:block;margin-top:7px}@media(max-width:650px){.window{width:calc(100% - 20px);height:calc(100% - 120px)}.apps{grid-template-columns:repeat(4,1fr)}.quick{left:10px;right:10px;width:auto}.pins button:nth-child(n+4){display:none}}
